import type { NextRequest } from "next/server";
import { listProducts, listProductsInCategory } from "@/lib/catalog";

export async function GET(request: NextRequest) {
  const category = request.nextUrl.searchParams.get("category");
  const products = category ? listProductsInCategory(category) : listProducts();

  // Send only the fields clients need, so the API keeps its shape when Product grows.
  return Response.json({
    data: products.map(({ slug, name, priceCents, inStock }) => ({ slug, name, priceCents, inStock })),
    total: products.length,
  });
}

