import { getProductBySlug } from "@/lib/catalog";

export async function GET(_request: Request, ctx: RouteContext<"/api/products/[slug]">) {
  const { slug } = await ctx.params;
  const product = getProductBySlug(slug);

  if (!product) {
    return Response.json({ error: `Unknown product: ${slug}` }, { status: 404 });
  }
  return Response.json(product);
}

"use server";

import { redirect } from "next/navigation";

export async function sendFeedback(formData: FormData) {
  const message = String(formData.get("message") ?? "").trim();

  // Anyone can call an action, not just your form, so check the input here too.
  if (message.length === 0 || message.length > 500) {
    throw new Error("Feedback must be 1 to 500 characters");
  }

  console.log(`Feedback: ${message}`);
  redirect("/feedback/thanks");
}

import { sendFeedback } from "./actions";

export default function FeedbackPage() {
  return (
    <main className="mx-auto max-w-2xl px-6 py-12">
      <h1 className="text-3xl font-semibold">Send feedback</h1>
      <form action={sendFeedback} className="mt-6 flex flex-col gap-3">
        <label htmlFor="message">What should we stock next?</label>
        <textarea id="message" name="message" required maxLength={500} className="rounded-md border p-2" />
        <button type="submit" className="self-start rounded-md bg-brand px-3 py-1.5 text-white">
          Send
        </button>
      </form>
    </main>
  );
}
